function expressionLips(x, y, warm, wry, tone) {
  // A tapered upper lip with a cupid's bow and a rounded lower lip.
  // Both follow the existing expression curve; the old mouth is not painted.
  const point = (t) => {
    const inv = 1-t, ax=x-2.5, ay=y+5, bx=x+0.5,
      by=y+(warm?8:wry?5.8:5), cx=x+3, cy=y+(wry?3.6:5);
    const dx=2*inv*(bx-ax)+2*t*(cx-bx),dy=2*inv*(by-ay)+2*t*(cy-by),len=Math.hypot(dx,dy);
    return {x:inv*inv*ax+2*inv*t*bx+t*t*cx,y:inv*inv*ay+2*inv*t*by+t*t*cy,nx:-dy/len,ny:dx/len};
  };
  const trace = (side) => {
    ctx.beginPath();
    for(let j=0;j<=24;j++) {
      const t=j/24,p=point(t),taper=Math.pow(Math.sin(Math.PI*t),0.8),
        width=side<0?taper*(0.9-0.45*Math.exp(-Math.pow((t-0.5)/0.12,2))):taper*0.9;
      const xx=p.x+p.nx*width*side,yy=p.y+p.ny*width*side;
      j?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy);
    }
    for(let j=24;j>=0;j--){const p=point(j/24);ctx.lineTo(p.x,p.y);}
    ctx.closePath();ctx.fill();
  };
  ctx.fillStyle=tone;trace(-1);trace(1);
  ctx.strokeStyle='#7c3c4d';ctx.lineWidth=0.34;ctx.beginPath();
  for(let j=0;j<=24;j++){const p=point(j/24);j?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y);}
  ctx.stroke();
}

